import { ChangeDetectionStrategy, Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { RawMaterialInward, RawMaterialInwardRequest } from '../../pages/raw-material-inward/raw-material-inward';
import { RawMaterialInwardService } from '../../services/raw-material-inward-service';
import { PoService } from '../../services/po-service';
import { PurchaseOrder } from '../../pages/purchase-order/purchase-order';
import { RawMaterial } from '../../models/invoice';
import { Supplier } from '../../pages/supplier/supplier';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  selector: 'app-add-raw-material-inward',
  imports: [CommonModule, FormsModule, ReactiveFormsModule],
  templateUrl: './add-raw-material-inward.html',
  styleUrl: './add-raw-material-inward.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AddRawMaterialInward implements OnInit {
  pos: PurchaseOrder[] = [];
  rawMaterials: RawMaterial[] = [];
  previousRWList: any[] = [];
  dataList: any[] = [];
  supplier: Supplier | null = null;
  selectedPO: PurchaseOrder | null = null;


  form!: FormGroup;

  constructor(
    private fb: FormBuilder,
    private inwardService: RawMaterialInwardService,
    private poService: PoService,
    private router: Router
  ) {}
  
 ngOnInit(): void {
  this.form = this.fb.group({
    purchaseOrderId: [null, Validators.required],
    rawMaterialId: [null, Validators.required], 
    inwardDate: [new Date().toISOString().split('T')[0], Validators.required],
    bags: [0, Validators.required],
    perKg: [0, Validators.required],
    grossQty: [{ value: 0, disabled: true }],
    purity: [0, [Validators.required, Validators.min(0), Validators.max(100)]],
    realWt: [{ value: 0, disabled: true }],
  });

  this.loadPOs();

 this.form.get('purchaseOrderId')?.valueChanges.subscribe(val => {
  console.log('🔥 Selected PO ID:', val); // now it will log the correct number
  if (val) this.onPOChange(val);
});


  // Auto-calc grossQty & realWt
  this.form.valueChanges.subscribe(val => {
    const gross = (val.bags || 0) * (val.perKg || 0);
    this.form.patchValue({ grossQty: gross }, { emitEvent: false });

    const real = gross * ((val.purity || 0) / 100);
    this.form.patchValue({ realWt: real }, { emitEvent: false });
  });
}

  

  loadPOs() {
    this.poService.getPO().subscribe(res => this.pos = res);
  }

onPOChange(purchaseOrderId: any) {
  const id = Number(purchaseOrderId);
  if (!id || isNaN(id)) return;

  this.poService.getPOById(id).subscribe((res: PurchaseOrder) => {
    this.selectedPO = res;
    this.supplier = res.supplier || null;

    this.rawMaterials = res.items
  .filter(i => i.rawMaterialDto) // lowercase r!
  .map(i => ({
    id: i.rawMaterialDto!.id,
    name: i.rawMaterialDto!.name,
    price: i.rawMaterialDto!.price
  } as RawMaterial));
    console.log('RawMaterials for PO:', this.rawMaterials);
  });
}

addToList() {
    if (this.form.invalid) return;

    const val = this.form.getRawValue(); // ✅ includes disabled fields
    const raw = this.rawMaterials.find((r) => r.id == val.rawMaterialId);

    this.dataList.push({
      inwardDate: val.inwardDate,
      rawMaterialId: val.rawMaterialId,
      rawMaterialName: raw?.name ?? '',
      bags: val.bags,
      perKg: val.perKg,
      grossQty: val.grossQty,
      purity: val.purity,
      realWt: val.realWt,
    });

    // Reset only item-specific fields
    this.form.patchValue({
      rawMaterialId: null,
      bags: 0,
      perKg: 0,
      grossQty: 0,
      purity: 0,
      realWt: 0,
    });
  }

  removeFromList(i: number) {
    this.dataList.splice(i, 1);
  }

save() {
  if (!this.dataList.length) return;
  const poId = this.form.get('purchaseOrderId')?.value;
  if (!poId) {
    alert('⚠️ Please select a Purchase Order first');
    return;
  }

  this.dataList.forEach(item => {
    const payload: RawMaterialInwardRequest = {
      purchaseOrderId: Number(poId),
      rawMaterialId: Number(item.rawMaterialId),
      supplierId: this.supplier?.id ?? 0,
      inwardDate: new Date(item.inwardDate).toISOString(),
      bags: Number(item.bags),
      perKg: Number(item.perKg),
      grossQty: Number(item.grossQty),
      purity: Number(item.purity),
      realWt: Number(item.realWt),
    };

    this.inwardService.addInward(payload).subscribe({
      next: (res) => { console.log('✅ Saved:', res); this.router.navigate(['/raw-material-inward']);},
      error: (err) => console.error('❌ Error:', err)
    });
  });
}

}